import { describe, expect, it } from "vitest";
import { clipId, slugify, assignIds, dedupe, sortClips, renderBook } from "../src/renderer.js";

const TITLE =
  "The Infinity Machine: Demis Hassabis, DeepMind, and the Quest for Superintelligence";

// Golden IDs generated by the retired Python sync.py against the real vault.
describe("clipId", () => {
  it("matches sync.py for a highlight", async () => {
    const id = await clipId({
      title: TITLE,
      type: "highlight",
      location: "496",
      text: "The idea that the gooey mass inside the skull contained some ineffable, unprogrammable something—consciousness? spirit?—was nothing more than biochauvinism.",
    });
    expect(id).toBe("75721b4f3aa3");
  });

  it("matches sync.py for a highlight with curly quotes", async () => {
    const id = await clipId({
      title: TITLE,
      type: "highlight",
      location: "1220",
      text: "“Intelligence measures an agent’s ability to achieve goals in a wide range of environments.”",
    });
    expect(id).toBe("7a5ab33ebd1b");
  });

  it("matches sync.py for a note", async () => {
    const id = await clipId({
      title: TITLE,
      type: "note",
      location: "3557",
      text: "Will AI create new paradigms that we cannot even understand? Think government, education, healthcare",
    });
    expect(id).toBe("ecea02091ab7");
  });

  it("renders a missing location as the string None, like Python", async () => {
    const a = await clipId({ title: "T", type: "highlight", location: null, text: "x" });
    const b = await clipId({ title: "T", type: "highlight", location: "None", text: "x" });
    expect(a).toBe(b);
  });
});

describe("slugify", () => {
  it("matches sync.py slugs", () => {
    expect(slugify(TITLE)).toBe(
      "the-infinity-machine-demis-hassabis-deepmind-and-the-quest-for-superintelligence"
    );
  });
  it("collapses punctuation runs and trims", () => {
    expect(slugify("  Peak: Secrets!! ")).toBe("peak-secrets");
  });
  it("falls back to untitled", () => {
    expect(slugify("!!!")).toBe("untitled");
  });
});

const AUTHOR = "Sebastian Mallaby";

function fixtureClips() {
  return [
    {
      title: TITLE, author: AUTHOR, type: "note", location: "3557", color: null,
      text: "Will AI create new paradigms that we cannot even understand? Think government, education, healthcare",
    },
    {
      title: TITLE, author: AUTHOR, type: "highlight", location: "1220", color: "blue",
      text: "“Intelligence measures an agent’s ability to achieve goals in a wide range of environments.”",
    },
    {
      title: TITLE, author: AUTHOR, type: "highlight", location: "496", color: "orange",
      text: "The idea that the gooey mass inside the skull contained some ineffable, unprogrammable something—consciousness? spirit?—was nothing more than biochauvinism.",
    },
  ];
}

const EXPECTED_FILE = `---
title: "The Infinity Machine: Demis Hassabis, DeepMind, and the Quest for Superintelligence"
author: "Sebastian Mallaby"
last_synced: 2026-07-10
---
<!-- GENERATED by Kindle Wiki Sync — edits are overwritten on every sync -->

# The Infinity Machine: Demis Hassabis, DeepMind, and the Quest for Superintelligence
*Sebastian Mallaby*

## Highlights

> The idea that the gooey mass inside the skull contained some ineffable, unprogrammable something—consciousness? spirit?—was nothing more than biochauvinism.
>
> — highlight · orange · loc. 496 ^75721b4f3aa3

> “Intelligence measures an agent’s ability to achieve goals in a wide range of environments.”
>
> — highlight · blue · loc. 1220 ^7a5ab33ebd1b

Note: Will AI create new paradigms that we cannot even understand? Think government, education, healthcare
— note · loc. 3557 ^ecea02091ab7
`;

describe("renderBook", () => {
  it("renders sorted clips in sync.py's format plus color", async () => {
    const clips = sortClips(dedupe(await assignIds(fixtureClips())));
    const out = renderBook(TITLE, AUTHOR, clips, "2026-07-10");
    expect(out).toBe(EXPECTED_FILE);
  });

  it("renders null author frontmatter and omits the byline", async () => {
    const clips = await assignIds([
      { title: "T", author: null, type: "highlight", location: "1", color: null, text: "x" },
    ]);
    const out = renderBook("T", null, clips, "2026-07-10");
    expect(out).toContain("author: null");
    expect(out).not.toContain("*null*");
    // color unknown -> meta line has no color segment
    expect(out).toContain("— highlight · loc. 1 ^");
  });
});

describe("dedupe", () => {
  it("keeps the first occurrence per id", async () => {
    const clip = { title: "T", author: null, type: "highlight", location: "1", color: "yellow", text: "same" };
    const withIds = await assignIds([clip, { ...clip, color: "pink" }]);
    const result = dedupe(withIds);
    expect(result).toHaveLength(1);
    expect(result[0].color).toBe("yellow");
  });
});

describe("sortClips", () => {
  it("sorts by location start, highlight before note", async () => {
    const withIds = await assignIds([
      { title: "T", author: null, type: "note", location: "10-12", color: null, text: "n" },
      { title: "T", author: null, type: "highlight", location: "10-12", color: null, text: "h" },
      { title: "T", author: null, type: "highlight", location: "2", color: null, text: "early" },
      { title: "T", author: null, type: "highlight", location: null, color: null, text: "nowhere" },
    ]);
    const order = sortClips(withIds).map((c) => c.text);
    expect(order).toEqual(["nowhere", "early", "h", "n"]);
  });
});
